operation.add:
public function setRobots($robots) {
	$this->robots = $robots;
}

public function getRobots() {
	return $this->robots;
}

public function setOgImage($og_image) {
	$this->og_image = $og_image;
}

public function getOgImage() {
	return $this->og_image;
}

if (isset($this->request->post['og_image'])) {
	$data['og_image'] = $this->request->post['og_image'];
} elseif (!empty($information_info)) {
	$data['og_image'] = isset($information_info['og_image']) ? $information_info['og_image'] : '';
} else {
	$data['og_image'] = '';
}

if (isset($this->request->post['noindex'])) {
	$data['noindex'] = 1;
} elseif (!empty($information_info) && !empty($information_info['noindex'])) {
	$data['noindex'] = 1;
} else {
	$data['noindex'] = 0;
}

if (isset($this->request->post['show_shipping_rates'])) {
	$data['show_shipping_rates'] = 1;
} elseif (!empty($information_info) && !empty($information_info['show_shipping_rates'])) {
	$data['show_shipping_rates'] = 1;
} else {
	$data['show_shipping_rates'] = 0;
}

if (isset($this->request->post['show_in_footer_info_links'])) {
	$data['show_in_footer_info_links'] = 1;
} elseif (!empty($information_info) && !empty($information_info['show_in_footer_info_links'])) {
	$data['show_in_footer_info_links'] = 1;
} else {
	$data['show_in_footer_info_links'] = 0;
}

if (!empty($information_info['noindex'])) {
	$this->document->setRobots('noindex, follow');
	$this->response->addHeader('X-Robots-Tag: noindex, follow');
}

if (!empty($information_info['og_image'])) {
	$og_image = trim($information_info['og_image']);

	if ($og_image !== '' && strpos($og_image, 'http://') !== 0 && strpos($og_image, 'https://') !== 0) {
		if ($this->request->server['HTTPS']) {
			$server = $this->config->get('config_ssl');
		} else {
			$server = $this->config->get('config_url');
		}

		$og_image = rtrim($server, '/') . '/' . ltrim($og_image, '/');
	}

	$this->document->setOgImage($og_image);
}

{% if robots %}
<meta name="robots" content="{{ robots }}" />
{% endif %}

{% set cyberpunks_default_og_image = 'catalog/view/theme/cybershops/media/head/og-altruist-bundle.png' %}
{% set cyberpunks_og_image = og_image ? og_image : cyberpunks_default_og_image %}
<meta property="og:image" content="{{ cyberpunks_og_image }}" />
